import 'package:flutter/material.dart';

import 'app_colors.dart';

class AppBackgrounds {
  AppBackgrounds._();

  static LinearGradient gradient(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final colors = isDark
        ? [
            const Color(0xFF020617),
            AppColors.primary.withValues(alpha: 0.018),
          ]
        : [
            AppColors.lightGradientFrom,
            const Color(0xFFEDF1F9),
            const Color(0xFFEAEFF8),
            AppColors.lightGradientTo,
            AppColors.primary.withValues(alpha: 0.06),
          ];
    final stops = isDark
        ? const [0.0, 0.18, 0.36, 0.56, 0.78, 0.94, 1.0]
        : const [0.0, 0.32, 0.58, 0.86, 1.0];

    return LinearGradient(
      begin: isDark ? const Alignment(0, -1) : const Alignment(-0.9, -0.85),
      end: isDark ? const Alignment(0, 1) : const Alignment(0.9, 0.95),
      colors: colors,
      stops: stops,
    );
  }
}
